1	/**
2	 * Everything the plugin decides, with nothing from the SDK in it.
3	 *
4	 * A key face is a function of what the plugin knows: whether it is
5	 * signed in, whether its socket is open, which runs are held, which is
6	 * pinned, and what that run last published. `reduce` moves the state on
7	 * one event at a time; the `*Face` functions read it. Keeping them pure
8	 * is what lets the twelve states a key can be in have a test each.
9	 */
10	
11	/**
12	 * What a deck may press, right now, in the pack's own words.
13	 *
14	 * Copied from `apps/web/src/run/offer.ts`: the plugin does not import
15	 * from `apps/web`, so this shape is mirrored rather than shared.
16	 */
17	export interface Offer {
18	  seq: number;
19	  primary: { id: "roll" | "carry-on" | "close" | "enter"; label: string; kind: string } | null;
20	  moves: Array<{ id: string; label: string }>;
21	  undo: { what: string } | null;
22	  /** Why a deck cannot press this, in words a key face can carry. */
23	  needsPage: string | null;
24	  presets: Array<{ kind: string; label: string; suggestions?: string[]; items?: number }>;
25	  /** The setups the run could hand out, empty where the run names no tool or is not live. */
26	  setups: Array<{ id: string; title: string }>;
27	}
28	
29	export type SessionState = "none" | "expired" | "ok";
30	export type SocketState = "closed" | "connecting" | "open";
31	export interface HeldRun {
32	  id: string;
33	  name?: string;
34	  packTitle?: string;
35	}
36	export interface Snapshot {
37	  unit?: number;
38	  words?: { unit: string };
39	  score?: { text: string };
40	  latest?: { text: string } | null;
41	  clocks?: Array<{ id: string; label: string; kind: "timer" | "stopwatch"; seconds: number | null; status: string; elapsedMs: number }>;
42	  standings?: Array<{ name: string; points: number; place: number }>;
43	  counters?: Array<{ id: string; label: string; value: number }>;
44	  resources?: Array<{ id: string; label: string; value: number; max: number | null }>;
45	  at?: string;
46	  offer?: Offer;
47	}
48	export interface DeckState {
49	  session: SessionState;
50	  /** Whether the streamer has switched the deck on. No socket while false. */
51	  on: boolean;
52	  /** Whether the last time it went off, it was the idle timer rather than a press. */
53	  idleOff: boolean;
54	  socket: SocketState;
55	  runs: HeldRun[];
56	  any: boolean;
57	  pinned: string | null;
58	  attached: string | null;
59	  snapshot: Snapshot | null;
60	  flash: { ref: string; ok: boolean; say?: string; until: number } | null;
61	}
62	export type Tone = "live" | "dim" | "refuse";
63	export interface Face {
64	  title: string;
65	  tone: Tone;
66	  when?: string;
67	  /** 0-1, set only for a running timer clock so a dial's indicator can draw it. */
68	  fraction?: number;
69	}
70	export type PressTarget =
71	  | { kind: "roll" }
72	  | { kind: "move"; id: string }
73	  | { kind: "answer"; preset: string; value: string }
74	  | { kind: "setup"; id: string; title: string };
75	export type MetricField = "score" | "unit" | "clock" | "latest" | "leader" | { counter: string } | { resource: string };
76	export type DeckEvent =
77	  | { t: "session"; state: SessionState }
78	  | { t: "on"; on: boolean; idle?: boolean }
79	  | { t: "socket"; state: SocketState }
80	  | { t: "runs"; runs: HeldRun[]; any: boolean }
81	  | { t: "pin"; id: string | null }
82	  | { t: "snapshot"; snapshot: Snapshot }
83	  | { t: "drove"; ref: string; ok: boolean; say?: string; seq?: number }
84	  | { t: "tick" };
85	
86	const FLASH_MS = 3000;
87	
88	/** How long a connection that is holding nothing waits before closing itself. */
89	export const IDLE_OFF_MS = 30 * 60_000;
90	
91	export function initial(): DeckState {
92	  return {
93	    session: "none",
94	    on: false,
95	    idleOff: false,
96	    socket: "closed",
97	    runs: [],
98	    any: false,
99	    pinned: null,
100	    attached: null,
101	    snapshot: null,
102	    flash: null,
103	  };
104	}
105	
106	export function attachedRun(state: DeckState): string | null {
107	  if (state.pinned) return state.runs.some((r) => r.id === state.pinned) ? state.pinned : null;
108	  return state.runs.length === 1 ? state.runs[0]!.id : null;
109	}
110	
111	export function reduce(state: DeckState, event: DeckEvent, now: number): DeckState {
112	  switch (event.t) {
113	    case "session":
114	      return event.state === "ok" ? { ...state, session: "ok" } : { ...initial(), session: event.state, pinned: state.pinned };
115	    case "on":
116	      // Going off is a full stop: no socket, nothing held, nothing to draw
117	      // a number from. The pin is a preference, not a holding, and stays.
118	      return event.on
119	        ? { ...state, on: true, idleOff: false }
120	        : { ...state, on: false, idleOff: event.idle === true, socket: "closed", runs: [], attached: null, snapshot: null };
121	    case "socket":
122	      return event.state === "open"
123	        ? { ...state, socket: "open" }
124	        : { ...state, socket: event.state, runs: [], attached: null, snapshot: null };
125	    case "runs": {
126	      const next = { ...state, runs: event.runs, any: event.any };
127	      const attached = attachedRun(next);
128	      // A run that went away takes its numbers with it; a run that is
129	      // still here keeps them until the next snapshot lands.
130	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
131	    }
132	    case "pin": {
133	      const next = { ...state, pinned: event.id };
134	      const attached = attachedRun(next);
135	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
136	    }
137	    case "snapshot":
138	      return { ...state, snapshot: event.snapshot };
139	    case "drove": {
140	      const flash = { ref: event.ref, ok: event.ok, ...(event.say ? { say: event.say } : {}), until: now + FLASH_MS };
141	      // A `drove` verdict is the freshest seq source: the next press
142	      // should not carry a seq gone stale while it was in flight.
143	      if (event.seq === undefined || !state.snapshot?.offer) return { ...state, flash };
144	      return { ...state, flash, snapshot: { ...state.snapshot, offer: { ...state.snapshot.offer, seq: event.seq } } };
145	    }
146	    case "tick": {
147	      const expired = state.flash !== null && state.flash.until <= now;
148	      // Controller ruling 3: a dial redraws every second while a clock is
149	      // running, so its remaining time keeps moving between snapshots. An
150	      // idle deck has nothing that changes on the tick, so it stays the
151	      // same object and nothing redraws.
152	      const running = state.snapshot?.clocks?.some((c) => c.status === "running") ?? false;
153	      if (!expired && !running) return state;
154	      return expired ? { ...state, flash: null } : { ...state };
155	    }
156	  }
157	}
158	
159	/** What a key says about the run once the deck is signed in and switched on. */
160	function held(state: DeckState): Face | null {
161	  if (state.socket !== "open") return { title: "Offline", tone: "dim" };
162	  if (state.pinned && !state.runs.some((r) => r.id === state.pinned)) return { title: "That run has ended", tone: "dim" };
163	  if (state.runs.length === 0) return state.any ? { title: "No run open", tone: "dim" } : { title: "Not synced", tone: "dim" };
164	  if (!state.attached) return { title: "Pick a run", tone: "dim" };
165	  return null;
166	}
167	
168	/** The state every key shares before any of them has something of its own to say. */
169	function common(state: DeckState): Face | null {
170	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
171	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
172	  // A key that depends on the connection says to make it first: the state
173	  // on top, the thing to do about it beneath.
174	  if (!state.on) return { title: "Not connected", tone: "dim", when: "press Connect" };
175	  return held(state);
176	}
177	
178	/** The run a deck is following, named, or nothing. */
179	function attachedName(state: DeckState): Face | null {
180	  const run = state.runs.find((r) => r.id === state.attached);
181	  if (!run) return null;
182	  return { title: run.name ?? run.packTitle ?? run.id, tone: "live", ...(run.packTitle && run.name ? { when: run.packTitle } : {}) };
183	}
184	
185	/**
186	 * The Connect key, which reports the connection rather than the run behind it.
187	 *
188	 * It is the one key that has something to say while the deck is off, so it
189	 * skips the "Not connected" every other key stops at and names the state it
190	 * is actually in - down by choice, down by the idle timer, or on its way up.
191	 */
192	export function connectFace(state: DeckState): Face {
193	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
194	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
195	  if (!state.on) return state.idleOff ? { title: "Idle · press to connect", tone: "dim" } : { title: "Offline", tone: "dim" };
196	  if (state.socket === "connecting") return { title: "Connecting", tone: "dim" };
197	  return held(state) ?? attachedName(state) ?? { title: "Connected", tone: "live" };
198	}
199	
200	/**
201	 * When a connection that is holding nothing should close itself.
202	 *
203	 * `since` is when it last had nothing to follow. Null means the clock is not
204	 * running at all - a deck following a live run never times out, however long
205	 * the stream goes, and a deck that is off or still dialing has nothing to
206	 * give up on.
207	 */
208	export function idleDeadline(state: DeckState, since: number): number | null {
209	  if (!state.on || state.socket !== "open" || state.runs.length > 0) return null;
210	  return since + IDLE_OFF_MS;
211	}
212	
213	function flashed(state: DeckState): Face | null {
214	  if (!state.flash || state.flash.ok) return null;
215	  return { title: state.flash.say ?? "No", tone: "refuse" };
216	}
217	
218	/** What the follow key was told about decisions. Re-exported by `actions/next.ts`. */
219	export type NextSettings = { stop?: boolean };
220	
221	/**
222	 * The decision the follow key takes for the streamer, or nothing.
223	 *
224	 * A checklist first, then a declaration with something to suggest: the two
225	 * the page publishes as presets. Placing the key and leaving *Stop at
226	 * decisions* unticked is the streamer choosing to skip the reading, which
227	 * is the rule `apps/web/src/run/handsFree.ts` asks for - a decision is
228	 * skipped only where somebody chose to skip it.
229	 */
230	function decision(offer: Offer, settings: NextSettings): Offer["presets"][number] | null {
231	  if (settings.stop) return null;
232	  const list = offer.presets.find((p) => p.kind === "checklist");
233	  if (list) return list;
234	  return offer.presets.find((p) => p.kind === "declareSubject" && (p.suggestions?.[0] ?? "") !== "") ?? null;
235	}
236	
237	/** What one press of the follow key sends, or nothing for it to send. */
238	export function nextPress(
239	  state: DeckState,
240	  settings: NextSettings,
241	): { press: "primary" } | { press: "answer"; answer: Record<string, string> } | null {
242	  const offer = state.snapshot?.offer;
243	  if (!offer) return null;
244	  if (offer.primary) return { press: "primary" };
245	  const d = decision(offer, settings);
246	  if (!d) return null;
247	  // The words the page takes for each preset, from `takePress.ts`.
248	  return d.kind === "checklist"
249	    ? { press: "answer", answer: { ticks: "all" } }
250	    : { press: "answer", answer: { subject: d.suggestions![0]! } };
251	}
252	
253	export function nextFace(state: DeckState, settings: NextSettings): Face {
254	  const c = common(state) ?? flashed(state);
255	  if (c) return c;
256	  const offer = state.snapshot?.offer;
257	  if (!offer) return { title: "Loading…", tone: "dim" };
258	  if (offer.primary) return { title: offer.primary.label, tone: "live" };
259	  // What the key would take, in the page's own words: the checklist's
260	  // button, or the name it would declare with the ask beneath it.
261	  const d = decision(offer, settings);
262	  if (d?.kind === "checklist") return { title: d.label, tone: "live" };
263	  if (d) return { title: d.suggestions![0]!, tone: "live", when: d.label };
264	  return { title: offer.needsPage ?? "Nothing to press", tone: offer.needsPage ? "refuse" : "dim" };
265	}
266	
267	export function pressFace(state: DeckState, target: PressTarget): Face {
268	  const c = common(state) ?? flashed(state);
269	  if (c) return c;
270	  const offer = state.snapshot?.offer;
271	  if (!offer) return { title: "Loading…", tone: "dim" };
272	  if (target.kind === "roll")
273	    return offer.primary?.id === "roll" ? { title: offer.primary.label, tone: "live" } : { title: "Nothing to roll", tone: "dim" };
274	  if (target.kind === "move") {
275	    const m = offer.moves.find((x) => x.id === target.id);
276	    return m ? { title: m.label, tone: "live" } : { title: "Not on offer", tone: "dim" };
277	  }
278	  if (target.kind === "setup") {
279	    return offer.setups.some((s) => s.id === target.id)
280	      ? { title: target.title, tone: "live", when: "Apply setup" }
281	      : { title: target.title, tone: "dim", when: "Not here" };
282	  }
283	  const p = offer.presets.find((x) => x.kind === target.preset);
284	  return p ? { title: target.value, tone: "live", when: p.label } : { title: target.value, tone: "dim", when: "Not now" };
285	}
286	
287	export function undoFace(state: DeckState): Face {
288	  const c = common(state) ?? flashed(state);
289	  if (c) return c;
290	  const undo = state.snapshot?.offer?.undo;
291	  // The key says "Undo" either way: what it would take back is the run's
292	  // business, and a key too small to read it is no help at the table.
293	  return undo ? { title: "Undo", tone: "live" } : { title: "Undo", tone: "dim" };
294	}
295	
296	export function runFace(state: DeckState): Face {
297	  return common(state) ?? attachedName(state) ?? { title: "Pick a run", tone: "dim" };
298	}
299	
300	/** How far a clock has moved since the snapshot that reported it, in ms. */
301	function clockElapsedMs(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): number {
302	  const since = c.status === "running" ? now - Date.parse(at) : 0;
303	  return c.elapsedMs + since;
304	}
305	
306	/** The arithmetic `stream-api.md` publishes, so a key agrees with a widget to the second. */
307	function clockText(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): string {
308	  const elapsed = clockElapsedMs(c, at, now);
309	  const ms = c.seconds === null ? elapsed : Math.max(0, c.seconds * 1000 - elapsed);
310	  const s = Math.floor(ms / 1000);
311	  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
312	}
313	
314	export function metricFace(state: DeckState, field: MetricField, now: number): Face {
315	  const c = common(state);
316	  if (c) return c;
317	  const snap = state.snapshot;
318	  if (!snap) return { title: "Loading…", tone: "dim" };
319	  if (field === "score") return { title: snap.score?.text ?? "—", tone: "live", when: "Score" };
320	  if (field === "unit") return { title: String(snap.unit ?? "—"), tone: "live", when: snap.words?.unit ?? "Unit" };
321	  if (field === "latest") return { title: snap.latest?.text ?? "—", tone: "live" };
