327	    const clock = snap.clocks?.find((x) => x.status === "running") ?? snap.clocks?.[0];
328	    if (!clock || !snap.at) return { title: "—", tone: "dim", when: "Clock" };
329	    const running = clock.kind === "timer" && clock.status === "running" && clock.seconds !== null;
330	    const fraction = running ? clockElapsedMs(clock, snap.at, now) / (clock.seconds! * 1000) : undefined;
