2	<html>
3	  <head lang="en">
4	    <title>Press Settings</title>
5	    <meta charset="utf-8" />
6	    <script src="https://sdpi-components.dev/releases/v4/sdpi-components.js"></script>
7	  </head>
8	
9	  <body>
10	    <sdpi-item label="Press">
11	      <select id="target"></select>
12	    </sdpi-item>
13	    <sdpi-item id="answer-row" label="Answer" style="display: none">
14	      <input id="answer" type="text" />
15	    </sdpi-item>
16	
17	    <div id="runlog-account"></div>
18	    <script src="account.js"></script>
19	    <script>
20	      // The moves and presets are the pack's own words, so they come from the
21	      // plugin on every appear rather than being listed here.
22	      (() => {
23	        const { streamDeckClient } = SDPIComponents;
24	        const target = document.getElementById("target");
25	        const answer = document.getElementById("answer");
26	        const answerRow = document.getElementById("answer-row");
27	        let current = null;
28	
29	        const option = (value, label) => {
30	          const o = document.createElement("option");
31	          o.value = JSON.stringify(value);
32	          o.textContent = label;
33	          return o;
34	        };
35	
36	        const fill = (moves, presets, setups) => {
37	          target.replaceChildren(option(null, "Set up"), option({ kind: "roll" }, "The waiting roll"));
38	          for (const m of moves) target.appendChild(option({ kind: "move", id: m.id }, m.label));
39	          for (const p of presets) target.appendChild(option({ kind: "answer", preset: p.kind, value: "" }, p.label));
40	          for (const s of setups) target.appendChild(option({ kind: "setup", id: s.id, title: s.title }, s.title));
41	          show();
42	        };
43	
44	        const show = () => {
45	          const chosen = current ? JSON.stringify(stripValue(current)) : "null";
46	          const match = [...target.options].find((o) => JSON.stringify(stripValue(JSON.parse(o.value))) === chosen);
47	          if (match) target.value = match.value;
48	          const isAnswer = current?.kind === "answer";
49	          answerRow.style.display = isAnswer ? "" : "none";
50	          answer.value = isAnswer ? (current.value ?? "") : "";
51	        };
52	
53	        // A preset option is identified by its kind, with the value typed beside it; a
54	        // setup option is identified by its id, so a renamed setup still matches.
55	        const stripValue = (t) =>
56	          t === null
57	            ? null
58	            : t.kind === "answer"
59	              ? { kind: "answer", preset: t.preset, value: "" }
60	              : t.kind === "setup"
61	                ? { kind: "setup", id: t.id }
62	                : t;
63	
64	        const save = () => streamDeckClient.setSettings(current ? { target: current } : {});
65	
66	        target.addEventListener("change", () => {
67	          current = JSON.parse(target.value);
68	          show();
69	          save();
70	        });
71	        answer.addEventListener("change", () => {
72	          if (current?.kind !== "answer") return;
73	          current = { ...current, value: answer.value };
74	          save();
75	        });
76	
77	        streamDeckClient.sendToPropertyInspector.subscribe(({ payload }) => {
78	          if (payload?.t === "offer") fill(payload.moves ?? [], payload.presets ?? [], payload.setups ?? []);
79	        });
80	        void streamDeckClient.getSettings().then(({ settings }) => {
81	          current = settings?.target ?? null;
82	          show();
83	        });
84	        fill([], [], []);
85	      })();
86	    </script>
87	  </body>
88	</html>
