18	
19	const held = (id: string, name = "Thursday") => ({ id, name, packTitle: "The Long Kiln" });
20	const offer: Offer = {
21	  seq: 42,
22	  primary: { id: "roll", label: "Roll the Weather", kind: "rollTable" },
23	  moves: [],
24	  undo: { what: "A dry wind." },
25	  needsPage: null,
26	  presets: [],
27	  setups: [],
28	};
29	const T = 1_000_000;
30	
31	// Signed in and switched on: the two things that had to be true before a
32	// key could say anything about a run, now that the socket is a state the
33	// streamer enters rather than a consequence of being configured.
34	const live = (): DeckState => reduce(reduce(initial(), { t: "session", state: "ok" }, T), { t: "on", on: true }, T);
35	const open = (runs = [held("s1")]): DeckState => {
36	  const s = reduce(live(), { t: "socket", state: "open" }, T);
37	  return reduce(s, { t: "runs", runs, any: true }, T);
38	};
39	
40	describe("what the keys say", () => {
41	  it("asks for a sign-in before anything else", () => {
42	    expect(nextFace(initial(), {})).toEqual({ title: "Sign in", tone: "dim" });
43	  });
44	  it("is offline with a session and no socket", () => {
45	    const s = live();
46	    expect(nextFace(s, {})).toEqual({ title: "Offline", tone: "dim" });
47	  });
48	  it("tells nothing synced from nothing open", () => {
49	    let s = live();
50	    s = reduce(s, { t: "socket", state: "open" }, T);
51	    expect(nextFace(reduce(s, { t: "runs", runs: [], any: false }, T), {})).toEqual({ title: "Not synced", tone: "dim" });
52	    expect(nextFace(reduce(s, { t: "runs", runs: [], any: true }, T), {})).toEqual({ title: "No run open", tone: "dim" });
53	  });
54	  it("attaches to the only held run without being asked", () => {
55	    let s = live();
56	    s = reduce(s, { t: "socket", state: "open" }, T);
57	    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
58	    expect(attachedRun(s)).toBe("s1");
59	    expect(runFace(s)).toEqual({ title: "Thursday", tone: "live", when: "The Long Kiln" });
60	  });
61	  it("asks to pick between two, and a pin decides", () => {
62	    let s = live();
63	    s = reduce(s, { t: "socket", state: "open" }, T);
64	    s = reduce(s, { t: "runs", runs: [held("s1"), held("s2", "Friday")], any: true }, T);
65	    expect(nextFace(s, {})).toEqual({ title: "Pick a run", tone: "dim" });
66	    expect(attachedRun(reduce(s, { t: "pin", id: "s2" }, T))).toBe("s2");
67	  });
68	  it("a pinned run that ended says so rather than drifting", () => {
69	    let s = live();
70	    s = reduce(s, { t: "socket", state: "open" }, T);
71	    s = reduce(s, { t: "pin", id: "s1" }, T);
72	    s = reduce(s, { t: "runs", runs: [held("s2", "Friday")], any: true }, T);
73	    expect(nextFace(s, {})).toEqual({ title: "That run has ended", tone: "dim" });
74	  });
75	  it("draws the offer's primary, and the reason when there is none", () => {
76	    let s = live();
77	    s = reduce(s, { t: "socket", state: "open" }, T);
78	    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
79	    s = reduce(s, { t: "snapshot", snapshot: { offer } }, T);
80	    expect(nextFace(s, {})).toEqual({ title: "Roll the Weather", tone: "live" });
81	    expect(undoFace(s)).toEqual({ title: "Undo", tone: "live" });
82	    const blocked = reduce(
83	      s,
84	      { t: "snapshot", snapshot: { offer: { ...offer, primary: null, needsPage: "Name the bowl on the page" } } },
85	      T,
86	    );
87	    expect(nextFace(blocked, {})).toEqual({ title: "Name the bowl on the page", tone: "refuse" });
88	  });
89	  it("says Undo either way, and dims it when there is nothing to take back", () => {
90	    let s = open();
91	    s = reduce(s, { t: "snapshot", snapshot: { offer: { ...offer, undo: null } } }, T);
92	    expect(undoFace(s)).toEqual({ title: "Undo", tone: "dim" });
93	  });
94	  it("flashes a refusal for three seconds, then goes back", () => {
95	    let s = live();
96	    s = reduce(s, { t: "socket", state: "open" }, T);
97	    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
98	    s = reduce(s, { t: "snapshot", snapshot: { offer } }, T);
99	    s = reduce(s, { t: "drove", ref: "r1", ok: false, say: "That moved on." }, T);
