101	    expect(nextFace(reduce(s, { t: "tick" }, T + 3001), {})).toEqual({ title: "Roll the Weather", tone: "live" });
102	  });
103	  it("ticks a running clock from the snapshot's own time", () => {
104	    let s = live();
105	    s = reduce(s, { t: "socket", state: "open" }, T);
106	    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
107	    const at = new Date(T).toISOString();
108	    s = reduce(
109	      s,
